with exploded as (select id, service, host, log_ts, level, latency_ms, status_code, attr_key, v from app_logs lateral view explode(context) x as attr_key, v) select id, service, host, log_ts, status_code, attr_key, lead(status_code, 1, 0) over (partition by host order by log_ts, id, attr_key) as next_status_code, cume_dist() over (partition by year(log_ts), attr_key order by status_code) as status_code_cume_dist from exploded
